import app from 'flarum/forum/app';
import Notification from 'flarum/forum/components/Notification';
/** Grup duyurusuyla aynı anda gelen site bildirimi: "N yeni paylaşım — ilki: …" */
export default class HighlightNotification extends Notification {
  icon() {
    return 'fas fa-bullhorn';
  }
  href() {
    const post = this.attrs.notification.subject();
    return post && post.discussion ? app.route.post(post) : app.route('index');
  }
  content() {
    const data = this.attrs.notification.content() || {};
    const label = data.label || '';
    const count = Number(data.count || 1);
    return count > 1 ? app.translator.trans('framio-notifications.forum.highlight_many', {
      count,
      label
    }) : app.translator.trans('framio-notifications.forum.highlight_one', {
      label
    });
  }
  excerpt() {
    return null;
  }
}