import app from 'flarum/forum/app';
import Group from 'flarum/common/models/Group';
import Icon from 'flarum/common/components/Icon';
import AbstractType from './AbstractType';
import { extractGroupIds, gambitFor } from '../utils/groupGambit';

/**
 * Matches groups by name, filtering the directory with a `group:` gambit.
 */
export default class GroupFilter extends AbstractType {
  resourceType() {
    return 'groups';
  }
  search(query) {
    this.suggestions = [];
    if (!query) {
      return;
    }
    const needle = query.toLowerCase();
    this.suggestions = app.store.all('groups').filter(group => {
      // The guest group would never match a real user.
      if (group.id() === Group.GUEST_ID) {
        return false;
      }
      return [group.nameSingular(), group.namePlural()].some(name => name.toLowerCase().includes(needle));
    });
  }
  renderKind() {
    return app.translator.trans('fof-user-directory.forum.search.kinds.group');
  }
  renderLabel(group) {
    const color = group.color();
    const icon = group.icon();
    return m("div", {
      className: `UserDirectorySearchLabel${color ? ' colored' : ''}`,
      style: color ? {
        backgroundColor: color
      } : undefined
    }, icon ? m(Icon, {
      name: icon
    }) : null, icon ? ' ' : null, group.namePlural());
  }
  applyFilter(params, group) {
    params.q = params.q ? `${params.q} ` : '';
    params.q += gambitFor(group.id());
  }
  initializeFromParams(params) {
    const ids = extractGroupIds(params.q ?? '');
    if (!ids.length) {
      return Promise.resolve([]);
    }
    return Promise.all(ids.map(id => app.store.find('groups', id)
    // A group referenced in the URL may since have been deleted; drop
    // it rather than failing the whole field.
    .catch(() => null))).then(groups => groups.filter(group => group !== null));
  }
}
flarum.reg.add('framio-community', 'user-directory/forum/searchTypes/GroupFilter', GroupFilter);